schema_ddl:
CREATE TABLE DEPTS (
    DNAME INTEGER,
    DPROJ INTEGER
);
CREATE TABLE PAYROLL (
    EMPL  INTEGER PRIMARY KEY,
    PDEPT INTEGER
);
CREATE TABLE TEAMS (
    TMEMBER INTEGER,
    TPROJ   INTEGER,
    FOREIGN KEY (TMEMBER) REFERENCES PAYROLL(EMPL)
);

counterexample:
INSERT INTO DEPTS (DNAME, DPROJ) VALUES ('SECURITY', 100);
INSERT INTO PAYROLL (EMPL, PDEPT) VALUES (101, 'OTHER');
INSERT INTO TEAMS (TMEMBER, TPROJ) VALUES (101, 100);

